CREATE TABLE supply_requests(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`buyer_id` BIGINT  NOT NULL,`crop_type` varchar(100)  NOT NULL,`quantity_needed` DECIMAL(10,2)  NOT NULL,`quality_requirements` text  NULL,`delivery_date_start` timestamp  NOT NULL,`delivery_date_end` timestamp  NOT NULL,`max_price_per_unit` DECIMAL(10,2)  NULL,`recurring` TINYINT(1)  NOT NULL DEFAULT 0,`recurrence_pattern` text  NULL,`is_emergency` TINYINT(1)  NOT NULL DEFAULT 0,`status` varchar(50)  NOT NULL DEFAULT 'open',`delivery_address` text  NULL,`delivery_latitude` DECIMAL(10,8)  NULL,`delivery_longitude` DECIMAL(11,8)  NULL,`delivery_pincode` varchar(10)  NULL,`delivery_state` varchar(100)  NULL,`delivery_district` varchar(100)  NULL,`notes` text  NULL,`embedding` vector(384)  NULL COMMENT 'Vector embedding for similarity matching (384 dimensions)',`embedding_cache_key` varchar(255)  NULL COMMENT 'Cache key for embedding to avoid regeneration')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;